const leads = $('Sheets — Leer LinkedIn').all();
const pending = leads.filter(item => {
  const estado = (item.json['Estado'] || '').trim().toLowerCase();
  return !estado;
});
for (let i = pending.length - 1; i > 0; i--) {
  const j = Math.floor(Math.random() * (i + 1));
  [pending[i], pending[j]] = [pending[j], pending[i]];
}
const batch = pending.slice(0, 10);
if (batch.length === 0) {
  return [{ json: { message: '\u2705 LinkedIn: todos los leads ya fueron contactados.', leads: [] } }];
}
const clean = (s) => (s || '').replace(/[*_`\[\]]/g, '');
const today = new Date();
const days = ['Dom', 'Lun', 'Mar', 'Mi\u00e9', 'Jue', 'Vie', 'S\u00e1b'];
const header = `\ud83d\udd17 *LinkedIn Outreach \u2014 ${days[today.getDay()]}*\n\ud83d\udcc5 ${today.toISOString().split('T')[0]}\n\ud83d\udccb ${batch.length} leads para contactar hoy\n\n`;
const selectedLeads = [];
const blocks = [];
for (let i = 0; i < batch.length; i++) {
  const l = batch[i].json;
  const name = clean(l['Nombre completo'] || 'Sin nombre');
  const company = clean(l['Empresa actual'] || '');
  const rawTitle = clean(l['T\u00edtulo actual'] || '');
  const title = rawTitle.length > 80 ? rawTitle.substring(0, 77) + '...' : rawTitle;
  const connectMsg = clean(l['Connect Request Message'] || 'Sin mensaje');
  const url = (l['LinkedIn URL'] || '').trim();
  let block = `*${i + 1}. ${name}*`;
  if (company) block += ` \u2014 ${company}`;
  block += '\n';
  if (title) block += `   ${title}\n`;
  if (url) block += `   ${url}\n`;
  block += `   \ud83d\udce9 ${connectMsg}\n\n`;
  blocks.push(block);
  selectedLeads.push({ linkedinUrl: url });
}
const footer = `\ud83d\udcca Pendientes: ${pending.length - batch.length} | Total: ${leads.length}`;
const messages = [];
let current = header;
for (const block of blocks) {
  if (current.length + block.length > 3800) {
    messages.push(current.trim());
    current = '';
  }
  current += block;
}
current += footer;
messages.push(current.trim());
return messages.map((msg, i) => ({
  json: {
    message: msg,
    leads: i === messages.length - 1 ? selectedLeads : []
  }
}));

// Reference the original Code node output, not Telegram's response
const allItems = $('Code \u2014 Seleccionar 10 Leads').all();
const allLeads = [];
for (const item of allItems) {
  const leads = item.json.leads || [];
  allLeads.push(...leads);
}
if (allLeads.length === 0) return [];
return allLeads.map(l => ({ json: { 'LinkedIn URL': l.linkedinUrl } }));
